import {e,Header,link} from './components.js';
export const fertilizerDay=(now=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);
const localDay=fertilizerDay;
const displayDate=value=>/^\d{4}-\d{2}-\d{2}$/.test(value||'')?value.split('-').reverse().join('.'):value||'Дата не указана';
export const fertilizerLocalTime=value=>{const d=new Date(value);if(Number.isNaN(d.getTime()))return '';const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(d).map(x=>[x.type,x.value]));return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}`;};
const card=body=>`<section class="card fertilizer-connected">${body}</section>`;
const button=(label,action,primary=false,disabled=false)=>`<button type="button" class="btn ${primary?'primary':'secondary'}" data-action="${e(action)}" ${disabled?'disabled':''}>${e(label)}</button>`;
const input=(label,name,value='',type='text',extra='')=>`<label>${e(label)}<input name="${e(name)}" value="${e(value??'')}" type="${type}" ${extra}></label>`;
const textarea=(label,name,value='')=>`<label>${e(label)}<textarea name="${e(name)}" rows="3" dir="auto">${e(value??'')}</textarea></label>`;
const select=(label,name,items,value='',empty='Выберите')=>`<label>${e(label)}<select name="${e(name)}"><option value="">${e(empty)}</option>${items.map(x=>`<option value="${e(x.id??x.key)}" ${String(x.id??x.key)===String(value)?'selected':''}>${e(x.name??x.display_name??x.label??x.key)}</option>`).join('')}</select></label>`;
const checkbox=(label,name,checked=false,extra='')=>`<label class="check-label"><input type="checkbox" name="${e(name)}" ${checked?'checked':''} ${extra}><span>${e(label)}</span></label>`;
const form=(name,body,label)=>`<form data-form="${name}" novalidate>${body}<div class="form-error" role="alert"></div><div class="confirmation-bar"><button type="submit" class="btn primary full">${e(label)}</button></div></form>`;
const note=text=>`<p class="note">${e(text)}</p>`;
const unit=u=>u==='L'?'л':u==='kg'?'кг':u||'Единица неизвестна';
const qty=v=>v==null?'Неизвестно':String(v);
const checked=v=>v===true||v==='on';
const issueLabels={LATE_EVIDENCE_REQUIRES_REVIEW_RESOLUTION_UNSUPPORTED:'После подтверждения факта получен отчёт о проблеме или частичном выполнении. Нужна проверка владельца; завершение этой проверки пока недоступно. Складской эффект не изменён.',AREA_UNKNOWN:'Проверьте площадь части',WORKER_UNKNOWN:'Выберите ответственного',DARI_REVIEW_REQUIRED:'Нужна проверенная инструкция на дари',LOCATION_UNKNOWN:'Выберите место хранения',DOSE_UNKNOWN:'Укажите норму на 1 da',INTENDED_TIME_UNKNOWN:'Укажите планируемое время',QUANTITY_PRECISION_UNSUPPORTED:'Расчёт выходит за допустимую точность',SUBSEQUENT_SAME_PLAN_SCOPE_UNSUPPORTED:'Дополнительное проведение этого плана пока недоступно',DISPATCH_REQUIRED:'Сначала проверьте и подтвердите поручение',OWNER_RESOLUTION_REQUIRED:'Укажите причину исправления или решения по проблеме',COMPLETED_CARD_REQUIRES_ALL_POSITIVE_COMPONENTS:'Часть можно завершить только после внесения всех её компонентов',ALL_ZERO_APPLICATION_UNSUPPORTED:'Полностью нулевое внесение не проводится; отчёт сохранён',INSUFFICIENT_OR_UNKNOWN_STOCK:'Недостаточно учтённого запаса либо запас неизвестен'};
const issueText=x=>typeof x==='string'?(issueLabels[x]||x):(x.message||x.reason||issueLabels[x.code]||x.code||JSON.stringify(x));
const issues=items=>items?.length?`<details open><summary>Что нужно уточнить · ${items.length}</summary><ul>${items.map(x=>`<li>${e(issueText(x))}</li>`).join('')}</ul></details>`:'';
const name=(items,id)=>items?.find(x=>x.id===id)?.name||items?.find(x=>x.id===id)?.display_name||id||'Не указано';
const status={DRAFT:'Черновик',APPROVED:'Поручение проверено',PARTIALLY_APPLIED:'Факт подтверждён частично',APPLIED:'Факт подтверждён',ACTUAL_REVERSED:'Складской факт отменён',ACTUAL_CORRECTED:'Складской факт исправлен'};
export const exactFertilizerNumber=(value,{zero=false,optional=false}={})=>{
 if((value==null||String(value).trim()==='')&&optional)return null;
 const s=String(value??'').trim();if(!/^\d{1,18}(?:[.,]\d{1,12})?$/.test(s)||(!zero&&!/[1-9]/.test(s)))throw Error('Укажите точное '+(zero?'неотрицательное':'положительное')+' количество.');return s;
};
export function latestBinding(refs,areaId,eventDate,kind='area'){
 return (refs.bindings||[]).filter(b=>b.work_area_id===areaId&&b.effective_from<=eventDate&&(kind==='worker'?b.default_worker_id:b.area_da!=null)).sort((a,b)=>String(b.effective_from).localeCompare(String(a.effective_from))||String(b.created_at||'').localeCompare(String(a.created_at||'')))[0]||null;
}
export function fertilizerEditRestriction(input){
 const cards=input?.cards||[];if(!cards.length)return null;
 const shape=c=>JSON.stringify({mix_label:c.mix_label,original_instruction:c.original_instruction??null,components:c.components.map(({component_id,...x})=>x)});
 if(cards.some(c=>c.components.some(x=>x.quantity_override!=null)))return 'Этот план содержит отдельные точные количества с обоснованием. Общий редактор не меняет их; исходные карточки сохранены. Редактирование и копирование такого варианта пока недоступны.';
 if(cards.some(c=>shape(c)!==shape(cards[0]))||(cards[0].original_instruction??null)!==(input.source?.original_text??null))return 'Этот план содержит разные смеси, порядок компонентов или отдельные исходные инструкции частей. Общий редактор не объединяет их. Редактирование и копирование такого варианта пока недоступны.';
 return null;
}
export function invalidateFertilizerReview(d,field){
 if(field.startsWith('reviewed_'))return;
 const perPart=/^(worker_|rendered_)(.+)$/.exec(field);
 if(perPart)d['reviewed_'+perPart[2]]='';
 else if(['greenhouse','date','intended_send_at','mix_label','notes'].includes(field)||/^(product_|location_|dose_|photo_|part_)/.test(field))for(const k of Object.keys(d))if(k.startsWith('reviewed_'))d[k]='';
}
export function fertilizerDraft(refs,{id,captured_at,product='',location='',input:saved=null}={}){
 const d={id,captured_at,date:localDay(),greenhouse:'',components:[],part_cards:{},component_cards:{},mix_label:'Внесение',origin:'owner',intended_send_at:localDay()+'T08:00'};
 const add=(p,l,dose,photo)=>{const key=crypto.randomUUID();d.components.push(key);Object.assign(d,{['product_'+key]:p||'', ['location_'+key]:l||'', ['dose_'+key]:dose??'', ['photo_'+key]:photo||''});return key;};
 if(!saved){add(product,location);return d;}
 d.saved_input=structuredClone(saved);d.saved_area_references={};d.saved_worker_references={};d.edit_restriction=fertilizerEditRestriction(saved);
 Object.assign(d,{greenhouse:saved.greenhouse_id,date:saved.event_date,intended_send_at:saved.intended_send_at?fertilizerLocalTime(saved.intended_send_at):'',notes:saved.source?.original_text||'',origin:saved.source?.origin||'owner',inbox_id:saved.source?.inbox_id||'',copied_from_plan_id:saved.copied_from_plan_id,copied_from_revision:saved.copied_from_revision,copy_reason:saved.copy_reason||''});
 const first=saved.cards?.[0];if(first){d.mix_label=first.mix_label;first.components.forEach(c=>add(c.product_id,c.location_id,c.dose_per_da,c.photo_source_id));}
 for(const c of saved.cards||[]){d.saved_area_references[c.work_area_id]=c.area_reference_id;d.saved_worker_references[c.work_area_id]=c.worker_reference_id;d['part_'+c.work_area_id]='on';d.part_cards[c.work_area_id]=c.card_id;d['worker_'+c.work_area_id]=c.worker_id||'';d['rendered_'+c.work_area_id]=c.rendered_text||'';d['reviewed_'+c.work_area_id]=c.rendering_reviewed?'on':'';d.component_cards[c.work_area_id]={};for(let i=0;i<c.components.length;i++)d.component_cards[c.work_area_id][d.components[i]]=c.components[i].component_id;}
 return d;
}
export function fertilizerPlanInput(d,refs){
 if(d.edit_restriction)throw Error(d.edit_restriction);
 if(!d.greenhouse)throw Object.assign(Error('Выберите теплицу.'),{field:'greenhouse'});
 if(!d.date)throw Object.assign(Error('Укажите дату внесения.'),{field:'date'});
 const parts=(refs.work_areas||[]).filter(p=>p.parent_id===d.greenhouse&&checked(d['part_'+p.id]));if(!parts.length)throw Error('Выберите хотя бы одну зарегистрированную часть.');
 const components=(d.components||[]).map(key=>{const p=refs.products.find(p=>p.id===d['product_'+key]);if(!p||!['kg','L'].includes(p.base_unit))throw Object.assign(Error('Выберите товар с базовой единицей кг или литры.'),{field:'product_'+key});return {key,product_id:p.id,location_id:d['location_'+key]||null,dose_per_da:exactFertilizerNumber(d['dose_'+key],{optional:true}),unit:p.base_unit,photo_source_id:d['photo_'+key]||null};});
 if(!components.length)throw Error('Добавьте хотя бы один компонент.');
 d.part_cards??={};d.component_cards??={};
 const cards=parts.map(p=>{const areaRef=d.saved_area_references?.[p.id]?(refs.bindings||[]).find(b=>b.id===d.saved_area_references[p.id]):latestBinding(refs,p.id,d.date),workerRef=d.saved_worker_references?.[p.id]?(refs.bindings||[]).find(b=>b.id===d.saved_worker_references[p.id]):latestBinding(refs,p.id,d.date,'worker')||latestBinding(refs,d.greenhouse,d.date,'worker');d.part_cards[p.id]??=crypto.randomUUID();d.component_cards[p.id]??={};return {card_id:d.part_cards[p.id],work_area_id:p.id,area_reference_id:areaRef?.id||null,mix_label:d.mix_label||'Внесение',worker_id:d['worker_'+p.id]||workerRef?.default_worker_id||null,worker_reference_id:(!d['worker_'+p.id]||d['worker_'+p.id]===workerRef?.default_worker_id)?(workerRef?.id||null):null,original_instruction:d.notes||null,rendered_text:d['rendered_'+p.id]||null,language:'fa',rendering_reviewed:checked(d['reviewed_'+p.id]),components:components.map(({key,...c})=>{d.component_cards[p.id][key]??=crypto.randomUUID();return {...c,component_id:d.component_cards[p.id][key],quantity_override:null,override_reason:null};})};});
 return {source:{form_id:d.id,captured_at:d.captured_at,source_kind:'OWNER_FORM',origin:d.origin||'owner',original_text:d.notes||null,inbox_id:d.inbox_id||null},greenhouse_id:d.greenhouse,event_date:d.date,intended_send_at:d.intended_send_at?new Date(d.intended_send_at+'+03:00').toISOString():null,copied_from_plan_id:d.copied_from_plan_id||null,copied_from_revision:d.copied_from_revision||null,copy_reason:d.copy_reason||null,cards};
}
export function fertilizerEditorView(d,refs,{editing=false}={}){
 if(d.edit_restriction)return Header('Сложный план сохранён','Редактор не меняет отдельные факты',true)+card(note(d.edit_restriction)+`<details><summary>Неизменённый исходный план</summary><pre class="source-json">${e(JSON.stringify(d.saved_input,null,2))}</pre></details>`);
 const parts=(refs.work_areas||[]).filter(p=>p.parent_id===d.greenhouse),products=(refs.products||[]).filter(p=>p.active!==false&&['kg','L'].includes(p.base_unit));
 return Header(editing?'Исправить план':'План внесения','Склад → части → проверка поручения',true)+card(form('fertilizer-plan',
 select('Теплица','greenhouse',refs.greenhouses||[],d.greenhouse)+input('Дата внесения','date',d.date,'date')+input('Планируемое время · Стамбул','intended_send_at',d.intended_send_at,'datetime-local')+note('Дата и 08:00 предложены по времени Стамбула; измените при необходимости. План не списывает склад. Время сохраняется, внешняя отправка не запускается.')+
 `<p class="notice">Выбрано частей: ${parts.filter(p=>checked(d['part_'+p.id])).length}. ${parts.filter(p=>checked(d['part_'+p.id])).map(p=>e(p.name)).join(', ')}</p><h2>Компоненты</h2>${d.components.map((key,i)=>{const p=products.find(p=>p.id===d['product_'+key]);return `<div class="fertilizer-component"><h3>Компонент ${i+1}</h3>${select('Товар','product_'+key,products,d['product_'+key])}${select('Откуда брать','location_'+key,refs.locations||[],d['location_'+key])}${input('Норма на 1 da · '+unit(p?.base_unit),'dose_'+key,d['dose_'+key],'text','inputmode="decimal"')}${note('Единица товара: '+unit(p?.base_unit)+'. Остаток не является дозировкой.')}<details><summary>Фото товара из сохранённого источника</summary>${input('ID оригинала изображения · необязательно','photo_'+key,d['photo_'+key])}</details>${d.components.length>1?button('Убрать компонент','fert-remove:'+key):''}</div>`;}).join('')}${button('Добавить удобрение','fert-add')}`+
 `<h2>Части теплицы</h2>${parts.length?button('Все части','fert-all')+parts.map(p=>{const b=d.saved_area_references?.[p.id]?(refs.bindings||[]).find(b=>b.id===d.saved_area_references[p.id]):latestBinding(refs,p.id,d.date);return checkbox(p.name+' · '+(b?b.area_da+' da':'площадь неизвестна'),'part_'+p.id,checked(d['part_'+p.id]));}).join(''):note(d.greenhouse?'В этой теплице части ещё не настроены. Точная схема недоступна.':'Сначала выберите теплицу.')}${link('Проверить площади и ответственных','fertilizer-references','btn secondary')}`+
 input('Название смеси / поручения','mix_label',d.mix_label)+textarea('Дополнительная инструкция · необязательно','notes',d.notes)+
 parts.filter(p=>checked(d['part_'+p.id])).map(p=>{const b=latestBinding(refs,p.id,d.date,'worker')||latestBinding(refs,d.greenhouse,d.date,'worker');return `<fieldset><legend>${e(p.name)}</legend>${select('Ответственный','worker_'+p.id,(refs.workers||[]).filter(w=>w.active!==false&&w.language==='fa'),d['worker_'+p.id]||b?.default_worker_id||'')}${b?note('Предложен по проверенному справочнику; можно изменить.'):note('Ответственный не настроен. Выберите явно.')}<details><summary>Инструкция на дари и проверка</summary>${textarea('Проверенная инструкция на дари','rendered_'+p.id,d['rendered_'+p.id])}${checkbox('Проверил смысл, числа, единицы и отрицания','reviewed_'+p.id,checked(d['reviewed_'+p.id]))}${note('Переводчик не подключён. Структурированные количества показываются отдельно.')}</details></fieldset>`;}).join('')+
 (d.copied_from_plan_id?textarea('Почему это новое отдельное внесение','copy_reason',d.copy_reason):'')+note('Введённые поля сохраняются как самостоятельный оригинал владельца.'),editing?'Проверить новую версию':'Рассчитать и проверить'));
}
export function fertilizerCards(cards){return (cards||[]).map(c=>card(`<h2>${e(c.work_area_name||c.part_name||c.work_area_id)}</h2><p>${e(c.mix_label||'Внесение')} · ${e(qty(c.area_da))} da</p><p>Ответственный: ${e(c.worker_name||c.worker_id||'Не указан')}</p>${(c.components||[]).map(x=>`<div class="fertilizer-quantity"><strong>${e(x.product_name||x.product_id)}</strong><span>${e(qty(x.proposed_quantity))} ${e(unit(x.unit))}</span><small>${e(qty(x.dose_per_da))} ${e(unit(x.unit))}/da · ${e(x.location_name||'Склад не выбран')}${x.photo_url?` · <a href="${e(x.photo_url)}" target="_blank" rel="noopener">Оригинал фото товара</a>`:''}</small></div>`).join('')}${(c.components||[]).filter(x=>x.quantity_override!=null).map(x=>note('Изменено владельцем: '+(x.product_name||x.product_id)+' · расчёт по норме '+qty(x.calculated_quantity)+' '+unit(x.unit)+' · '+(x.override_reason||''))).join('')}${c.prepared_instruction?`<details><summary>Подготовленное представление</summary><p>${e(c.prepared_instruction)}</p></details>`:''}${c.rendered_text?`<blockquote dir="auto">${e(c.rendered_text)}</blockquote>`:''}${issues(c.issues)}`)).join('');}
export function fertilizerTotals(totals,refs={}){return `<div class="fertilizer-totals">${(totals||[]).map(t=>`<p><strong>${e(t.product_name||name(refs.products,t.product_id))}</strong><span>${e(qty(t.quantity))} ${e(unit(t.unit))}</span></p>`).join('')}</div>`;}
export function fertilizerPreviewView(preview,refs,editing=false){return Header('Проверить план','Расчёт сервера · склад ещё не списывается',true)+fertilizerCards(preview.cards)+card('<h2>Всего по выбранным частям</h2>'+fertilizerTotals(preview.totals,refs)+issues(preview.issues)+button(editing?'Сохранить новую версию':'Сохранить план','fert-save',true)+button('Исправить один факт','fert-edit-preview')+note('Недостающая инструкция или площадь не мешает сохранить черновик. Поручение требует отдельной проверки.'));}
export function fertilizerCalendarView(result,filters,refs){return Header('Внесения','План, отчёты и подтверждённый факт',true)+card(form('fertilizer-filters',input('С даты','date_from',filters.date_from,'date')+input('По дату','date_to',filters.date_to,'date')+select('Теплица','greenhouse_id',refs.greenhouses||[],filters.greenhouse_id||'','Все теплицы'),'Показать')+link('Новое внесение','fertilizer-new','btn primary'))+((result.items||[]).length?(result.items||[]).map(p=>card(link(e(p.greenhouse_name||p.greenhouse_id)+' · '+e(displayDate(p.event_date)),'fertilizer-plan/'+p.id,'')+`<p>${e(status[p.status]||p.status)} · частей ${e(p.card_count)}</p><small>Сделано: ${e(p.done_count??0)} · частично: ${e(p.partial_count??0)} · проблемы: ${e(p.problem_count??0)}</small>${p.late_evidence_count?note('Отчёты после подтверждённого факта: '+p.late_evidence_count+'. Требуют отдельной проверки; её завершение пока недоступно.'):''}${p.needs_owner_review?'<p class="notice amber">Нужна проверка владельца</p>':''}`)).join(''):card('Внесений за этот период пока нет.'));}
export function fertilizerDetailView(plan,refs){return Header('Внесение · '+displayDate(plan.input.event_date),status[plan.status]||plan.status,true)+fertilizerCards(plan.cards)+card('<h2>Итог плана</h2>'+fertilizerTotals(plan.totals,refs)+issues(plan.issues)+`<div class="page-actions">${plan.actual?'':link('Исправить план','fertilizer-edit/'+plan.id,'btn secondary')}${button('Подтвердить поручение в TEST','fert-dispatch',true,!plan.can_dispatch)}${link('Проверить фактический расход','fertilizer-actual/'+plan.id,'btn primary')}${button('Новый план по образцу','fert-copy')}</div>`+note('Подтверждение открывает проверенные карточки во внутреннем TEST работника. Реальных сообщений нет.'))+card(`<h2>Отчёты</h2>${(plan.reports||[]).map(r=>`<div class="list-row"><strong>${e(r.worker_name||name(refs.workers,r.worker_id))} · ${e({DONE:'Сделано',PARTIAL:'Частично',PROBLEM:'Проблема'}[r.response]||r.response)}</strong><p>${e(r.work_area_name||r.card_id)}</p><p dir="auto">${e(r.source_snapshot?.comment??r.comment??'Без комментария')}</p><small>Версия ${e(r.source_snapshot?.expected_revision??r.revision??r.expected_revision)} · ${e(r.source_snapshot?.captured_at??r.captured_at)}</small></div>`).join('')||'<p>Отчётов пока нет.</p>'}`)+(plan.actual?card(`<h2>${e(status[plan.status]||'Подтверждённый факт')}</h2><p>${e(plan.status==='ACTUAL_REVERSED'?'Исходное движение отменено. История сохраняется.':plan.status==='ACTUAL_CORRECTED'?'Открывайте текущее исправленное движение; исходный факт сохранён.':'Складской эффект создан один раз.')}</p>${link('Движения и исходник','stock-event/'+(plan.actual.current_application_id||plan.actual.application_id||plan.actual.inventory_event_id||plan.actual.event_id),'btn secondary')}${note(plan.remainder?.length?'Есть неподтверждённый остаток плана. Дополнительное проведение этого же плана в этой версии не поддерживается. Новый план не заменяет закрытие этого остатка.':'Принятый факт хранится отдельно от поздних отчётов.')}`):'')+card(`<details><summary>Оригинал и история версий</summary><pre class="source-json">${e(JSON.stringify(plan.input,null,2))}</pre>${(plan.revisions||[]).map(r=>`<details><summary>Версия ${e(r.revision)}</summary><pre class="source-json">${e(JSON.stringify(r.source_snapshot||r.input,null,2))}</pre></details>`).join('')}</details>`);}
export function fertilizerReferenceView(refs,d){return Header('Площади и ответственные','Однократная проверка реальных справочников',true)+card(form('fertilizer-reference',select('Зарегистрированная часть / теплица','work_area_id',refs.work_areas||[],d.work_area_id)+select('Принятое значение CURRENT · необязательно','canonical_key',(refs.canonical_candidates||[]).map(c=>({...c,label:[c.greenhouse_name,c.part_name,c.area_da?c.area_da+' da':c.worker_name].filter(Boolean).join(' · ')})),d.canonical_key,'Значение проверено вручную')+input('Площадь, da · для части','area_da',d.area_da,'text','inputmode="decimal"')+select('Ответственный · необязательно','default_worker_id',(refs.workers||[]).filter(w=>w.active!==false&&w.language==='fa'),d.default_worker_id,'Не меняется')+input('Действует с','effective_from',d.effective_from||localDay(),'date')+textarea('Основание проверки','verification',d.verification)+note('Совпадение названий лишь подсказка. Подтвердите соответствие реальному ID; прежние планы не пересчитываются.'),'Подтвердить справочник'))+card((refs.bindings||[]).map(b=>`<p>${e(name(refs.work_areas,b.work_area_id))}: ${e(b.area_da==null?'':b.area_da+' da')} ${e(b.default_worker_id?name(refs.workers,b.default_worker_id):'')} · с ${e(b.effective_from)}</p>`).join('')||'<p>Проверенных значений пока нет.</p>');}
export function fertilizerActualDraft(plan,id,captured_at){const d={id,captured_at,date:plan.input.event_date};for(const c of plan.cards||[]){for(const x of c.components||[]){const key=c.card_id+'_'+x.component_id;const q=(plan.proposed_actual_lines||[]).find(l=>l.card_id===c.card_id&&l.component_id===x.component_id);d['quantity_'+key]=q?.quantity??'';d['disposition_'+key]='APPLIED';}}return d;}
export function fertilizerActualInput(d,plan){const lines=[];for(const c of plan.cards||[])for(const x of c.components||[]){const key=c.card_id+'_'+x.component_id;if(!checked(d['selected_'+key]))continue;const report=c.current_report;if(!report?.id)throw Error('У выбранной части нет текущего отчёта работника.');lines.push({card_id:c.card_id,component_id:x.component_id,report_id:report.id,quantity:exactFertilizerNumber(d['quantity_'+key],{zero:true}),disposition:d['disposition_'+key]||'APPLIED',reason:d['reason_'+key]||null});}if(!lines.length)throw Error('Выберите фактически проверенные компоненты.');return {source:{form_id:d.id,captured_at:d.captured_at,source_kind:'OWNER_FORM'},expected_version:plan.version,revision:plan.revision,event_date:d.date,duplicate_reviewed:checked(d.duplicate_reviewed),lines,completed_card_ids:(plan.cards||[]).filter(c=>checked(d['completed_'+c.card_id])).map(c=>c.card_id)};}
export function fertilizerActualView(plan,d,preview=null){if(plan.actual)return Header(status[plan.status]||'Факт уже подтверждён','Повторного списания не будет',true)+card(note('Дополнительное проведение остатка этого плана в текущей версии не поддерживается. Неизвестный или неподтверждённый остаток остаётся открытым.')+link('К плану и движениям','fertilizer-plan/'+plan.id,'btn primary'));
 const fields=(plan.cards||[]).map(c=>!c.current_report?`<fieldset><legend>${e(c.work_area_name||c.part_name||c.work_area_id)}</legend><p>Ждём отчёт. Фактические количества неизвестны; эта часть пока не может войти в подтверждение.</p><details><summary>План и сохранённые значения</summary>${(c.components||[]).map(x=>{const key=c.card_id+'_'+x.component_id;return `<p>${e(x.product_name||x.product_id)} · план ${e(qty(x.proposed_quantity))} ${e(unit(x.unit))} · сохранённый ввод ${e(qty(d['quantity_'+key]===''?null:d['quantity_'+key]))}</p>`;}).join('')}</details></fieldset>`:`<fieldset><legend>${e(c.work_area_name||c.part_name||c.work_area_id)}</legend><p>Отчёт: ${e({DONE:'Сделано',PARTIAL:'Частично',PROBLEM:'Проблема'}[c.current_report?.response]||'Нет отчёта')}</p>${(c.components||[]).map(x=>{const key=c.card_id+'_'+x.component_id,q=(plan.proposed_actual_lines||[]).find(l=>l.card_id===c.card_id&&l.component_id===x.component_id),uncertain=q?.quantity==null||c.current_report?.response!=='DONE';return `<div class="fertilizer-component"><div class="fertilizer-quantity"><strong>${e(x.product_name||x.product_id)}</strong><span>${e(qty(d['quantity_'+key]===''?null:d['quantity_'+key]))} ${e(unit(x.unit))}</span><small>План: ${e(qty(x.proposed_quantity))} · отчёт: ${e(qty(q?.quantity))} ${e(unit(x.unit))}</small></div>${checkbox('Включить в это внесение','selected_'+key,checked(d['selected_'+key]))}<details ${uncertain?'open':''}><summary>${uncertain?'Уточнить факт и причину':'Исправить количество или действие'}</summary>${select('Фактическое действие','disposition_'+key,[{id:'APPLIED',name:'Внесено'},{id:'NOT_APPLIED',name:'Не внесено · явный ноль'}],d['disposition_'+key]||'APPLIED')}${input('Факт, '+unit(x.unit)+' · пусто означает неизвестно','quantity_'+key,d['quantity_'+key],'text','inputmode="decimal"')}${textarea('Причина отличия / явного нуля','reason_'+key,d['reason_'+key])}</details></div>`;}).join('')}${checkbox('Вся часть полностью выполнена','completed_'+c.card_id,checked(d['completed_'+c.card_id]))}</fieldset>`).join('');
 const products={products:(plan.cards||[]).flatMap(c=>c.components||[]).map(c=>({id:c.product_id,name:c.product_name}))};
 return Header('Проверить фактический расход','Одна проверка одного складского события',true)+card(form('fertilizer-actual',input('Дата факта','date',d.date,'date')+note('Дата предложена из плана. Проверьте и измените её на фактическую; это не факт из отчёта работника.')+button('Выбрать известный выполненный объём','fert-select-known')+note('Выбор включает только текущие отчёты «Сделано» с известными количествами. Он ещё ничего не проводит.')+fields+checkbox('Проверил отсутствие другой записи того же факта','duplicate_reviewed',checked(d.duplicate_reviewed))+note('Неизвестный остаток не станет нулём; последующее проведение остатка этого же плана пока не поддерживается.'),'Проверить складской эффект'))+(preview?card('<h2>Предстоящий эффект</h2>'+fertilizerTotals(preview.totals,products)+issues(preview.issues)+note('Выбрано строк: '+(preview.selected_scope?.length??preview.input?.lines?.length??0)+'. Неподтверждённый остаток: '+(preview.remainder?.length??0))+button('Подтвердить фактическое внесение','fert-confirm-actual',true,!preview.can_confirm)+note('Изменение любого поля требует повторной проверки.')):'');}
